insert into public.announcements (label, title, description, details, image_url, gallery, is_published, position) values
  ('PRIVATE TOUR · นครพนม–ท่าแขก', 'ทริปนครพนม–ลาว (ท่าแขก) 3 วัน 2 คืน', 'ทริปสุดคุ้ม นครพนม–ลาว (ท่าแขก) 3 วัน 2 คืน เช็คอินท่าฝรั่ง นั่งรถตู้ VIP กินดี เที่ยวสบาย มีทีมงานดูแล เริ่มต้น 7,000 บาท/ท่าน หรือจองคู่ 13,000 บาท', array['เที่ยวสบาย เดินทางสบาย ไปกับทริป “นครพนม–ลาว (ท่าแขก)” 3 วัน 2 คืน ชวนครอบครัวและคนที่คุณรักมาร่วมเดินทางท่องเที่ยว พักผ่อนจิตใจ ไหว้พระธาตุศักดิ์สิทธิ์ริมฝั่งโขงที่นครพนม แล้วข้ามโขงไปสัมผัสบรรยากาศความสงบและธรรมชาติที่สมบูรณ์ของเมืองท่าแขก แขวงคำม่วน สปป.ลาว พร้อมไฮไลต์เช็คอินนอนแพริมน้ำใสสะอาดที่ “ท่าฝรั่ง”', 'ทริปนี้เราดูแลคุณอย่าง VIP', '• นั่งรถตู้ระดับพรีเมียม Hyundai H-1 เบาะนุ่ม นั่งสบายตลอดการเดินทาง', '• อิ่มอร่อยกับอาหารทุกมื้อตามแพลนทริป ไม่ต้องเลือกร้านเองให้ยุ่งยาก', '• ทีมงานมืออาชีพดูแลใกล้ชิด ใส่ใจในทุกรายละเอียดเพื่อความสุขของทุกคน', 'ราคาพิเศษจองแพ็กคู่: เพียง 13,000 บาท / 2 ท่าน (จากปกติท่านละ 7,000 บาท เฉลี่ยคนละ 6,500 บาท)', 'แพลนวันหยุดนี้ให้รางวัลตัวเองและคนข้าง ๆ ด้วยการออกไปเที่ยวด้วยกัน สร้างความทรงจำดี ๆ ร่วมกันนะคะ', 'สนใจสอบถามรายละเอียดแพลนการเดินทางเพิ่มเติม โทร: 098-1045788 (ครูจิ๋ว) / 091-7801023 (คุณจูเนียร์)', '#เที่ยวแบบครอบครัว #ทัวร์ทำบุญ #เที่ยวลาวกลาง #ท่าแขกคำม่วน #ท่าฝรั่งลาว #เช่ารถตู้พร้อมคนขับ #เที่ยวสนุกเดินทางสบาย #นครพนมเที่ยวไหนดี #สปปลาว']::text[], '/announcements/nakhon-phanom-thakhek-trip.jpg', array['/announcements/nakhon-phanom-thakhek-trip.jpg', '/announcements/nakhon-phanom-thakhek-itinerary.jpg']::text[], true, 0),
  ('ENGLISH COURSE · ม.ต้น', 'คอร์สภาษาอังกฤษ ม.1–ม.3 ภาคเรียนที่ 2/2569', 'ปูพื้นฐานไวยากรณ์และโครงสร้างภาษา พร้อมเตรียมสอบเข้า ม.4 ห้องพิเศษและโครงการดัง รับจำนวนจำกัด 15 ที่นั่ง', array['คอร์สภาษาอังกฤษสำหรับนักเรียน ม.1–ม.3 ภาคเรียนที่ 2/2569 โดย Learning Plus by Kru Jew', '• ปูพื้นฐานไวยากรณ์และโครงสร้างภาษาให้แข็งแรง พร้อมก้าวเข้าสู่ระดับ Advanced', '• เตรียมสอบเข้า ม.4 ห้องพิเศษและโครงการดังของโรงเรียน', 'รับจำนวนจำกัดเพียง 15 ที่นั่ง', 'เรียนวันเสาร์และอาทิตย์ เวลา 10:30–12:00 น. เริ่ม 31 ตุลาคม ถึง 7 มีนาคม 2570', 'ติดต่อสอบถามหรือจองที่นั่ง: ครูจิ๋ว 098-104-5788 หรือสแกน QR Code บนภาพประกาศ']::text[], '/announcements/english-m1-m3.jpg', array['/announcements/english-m1-m3.jpg']::text[], true, 1),
  ('ENGLISH COURSE · ม.ปลาย', 'คอร์สภาษาอังกฤษ ม.4–ม.6 ภาคเรียนที่ 2/2569', 'ปรับพื้นฐานและเตรียมสอบมหาวิทยาลัย ครอบคลุม TOEFL ITP, IELTS, KEPT, CU-TEP, NETSAT, TGAT และ A-Level รับ 15 ที่นั่ง', array['คอร์สภาษาอังกฤษสำหรับนักเรียน ม.4–ม.6 ภาคเรียนที่ 2/2569 โดย Learning Plus by Kru Jew เน้นปรับพื้นฐานและเตรียมสอบเข้ามหาวิทยาลัย', '• TOEFL ITP: เพิ่มทักษะ Academic English', '• IELTS: ฝึกฟัง พูด อ่าน เขียนครบทุกพาร์ต', '• KEPT: เน้น Grammar และ Vocabulary', '• CU-TEP: เตรียมสอบ CU-TEP', '• NETSAT: เจาะลึกข้อสอบ NETSAT', '• TGAT และ A-Level: เตรียมพร้อมสอบเข้ามหาวิทยาลัย', 'เริ่มเรียน 31 ตุลาคม 2569 ถึง 14 มีนาคม 2570 การันตี 50 ชั่วโมงขึ้นไป รับจำนวนจำกัด 15 ที่นั่ง', 'ติดต่อสอบถามหรือจองที่เรียน: ครูจิ๋ว 098-104-5788, LINE @krujewenglish หรือสแกน QR Code บนภาพประกาศ']::text[], '/announcements/english-m4-m6.jpg', array['/announcements/english-m4-m6.jpg']::text[], true, 2),
  ('SUMMER UK 2027', 'ใช้ชีวิตแบบชาวลอนดอน เรียนภาษาอังกฤษที่ Canterbury', 'แพ็กเกจ All-inclusive เรียน Speaking for IELTS 30 ชั่วโมง พร้อมที่พัก อาหาร กิจกรรม ทัศนศึกษา ตั๋วเครื่องบินและประกันการเดินทาง', array['เรียนภาษาอังกฤษพร้อมสัมผัสชีวิตจริงในเมือง Canterbury ประเทศอังกฤษ กับ Learning Plus by Kru Jew และ Stafford House', '• เรียนคอร์ส Speaking for IELTS 30 ชั่วโมง พร้อมใบรับรองจากสถาบัน', '• พัก Residence Apartment ใจกลางเมือง ใกล้สถาบัน', '• รวมอาหารและการเดินทางตามโปรแกรม', '• ทัศนศึกษาและกิจกรรมใน London และ Canterbury', '• รวมตั๋วเครื่องบินไป–กลับ ค่าวีซ่า และประกันภัยการเดินทาง', 'เดินทางวันที่ 17 เมษายน ถึง 1 พฤษภาคม 2570', 'ราคาพิเศษ 169,000 บาท สมัครและจองคอร์สวันนี้รับส่วนลด 5,000 บาท ตามเงื่อนไขที่ระบุในภาพประกาศ', 'สอบถามข้อมูลเพิ่มเติมและจองสิทธิ์ได้กับ Learning Plus by Kru Jew']::text[], '/announcements/canterbury-summer.jpg', array['/announcements/canterbury-summer.jpg']::text[], true, 3),
  ('LIVE · LEARN · EXPLORE', 'สัมผัสชีวิตจริงและเรียนรู้ที่ Canterbury', 'เรียนภาษาอังกฤษผ่านประสบการณ์จริง พัก Residence Apartment ใจกลางเมือง พร้อมกิจกรรมและทัศนศึกษาที่ออกแบบให้เรียนรู้วัฒนธรรมอย่างเต็มที่', array['Experience Life in Canterbury: เรียนภาษาอังกฤษผ่านประสบการณ์จริง พร้อมใช้ชีวิตในเมืองแคนเทอร์เบอรี ประเทศอังกฤษ', '• พัก Residence Apartment ใจกลางเมืองแคนเทอร์เบอรี และเรียนรู้วิถีชีวิตแบบคนท้องถิ่น', '• Intensive IELTS Course ฝึกทักษะการสื่อสารและการพูดภาษาอังกฤษอย่างเต็มที่', '• All-inclusive Living รวมที่พัก อาหาร และการดูแลระหว่างการเดินทางตามโปรแกรม', '• กิจกรรมและทัศนศึกษาใน London และ Canterbury เพื่อเรียนรู้วัฒนธรรมจากประสบการณ์จริง', 'ติดต่อสอบถาม: +66 98104 5788 หรือ interplus4consulting@gmail.com']::text[], '/announcements/canterbury-experience.jpg', array['/announcements/canterbury-experience.jpg']::text[], true, 4),
  ('EDUCATION PLAN · UK 2027', 'แผนการชำระเงินโปรแกรม Canterbury UK 2027', 'ราคาพิเศษ 164,000 บาทเมื่อจองล่วงหน้า แบ่งชำระ 3 งวด รวมวีซ่า ที่พัก คอร์สเรียน อาหาร ประกัน และทริปท่องเที่ยว', array['แผนการชำระเงินโปรแกรมเรียน Summer อังกฤษ 2027: Education Plan Canterbury UK 2027', 'ราคาพิเศษ 164,000 บาท ลด 5,000 บาทเมื่อจองล่วงหน้าตามเงื่อนไขในภาพประกาศ', '• งวดที่ 1 วันจองคอร์ส: 30% จำนวน 50,700 บาท จองก่อนสิ้นเดือนธันวาคมรับสิทธิ์ส่วนลด 5,000 บาท', '• งวดที่ 2 สิ้นเดือนมกราคม 2027: 30% จำนวน 50,700 บาท', '• งวดที่ 3 สิ้นเดือนกุมภาพันธ์ 2027: 40% จำนวน 67,600 บาท', 'รวมตั๋วเครื่องบิน วีซ่า ที่พัก คอร์สเรียน อาหาร ประกัน และทริปท่องเที่ยวตามรายละเอียดในภาพประกาศ']::text[], '/announcements/canterbury-payment-plan.jpg', array['/announcements/canterbury-payment-plan.jpg']::text[], true, 5);
